package siit

import (
	"slices"

	"github.com/google/gopacket/layers"
)

// RFC 7915 Sections 4.1 and 5.1 (ICMP errors generated by the translator)

// The errors are sent back to the sender in the family of the packet that caused them. ICMPv4 errors come from the
// router address, ICMPv6 errors from the router address mapped to IPv6.

func (t *Translator) generateIPv4TimeExceeded(ip *layers.IPv4) Packet {
	outer := &layers.IPv4{
		Version: 4, IHL: 5, Protocol: layers.IPProtocolICMPv4, TTL: 64,
		SrcIP: t.ipv4RouterAddress, DstIP: ip.SrcIP,
	}

	// RFC 1812 Section 4.3.2.3 (SHOULD): "the ICMP datagram SHOULD contain as much of the original datagram as possible
	// without the length of the ICMP datagram exceeding 576 bytes."
	quote := slices.Concat(ip.Contents, ip.Payload)
	message := newICMPv4(11, 0, 0, quote[:min(len(quote), ipv4ICMPErrorPayloadMaximum)])
	return serializePacket(completeOptions, outer, message)
}

func (t *Translator) generateIPv6TimeExceeded(ip *layers.IPv6) Packet {
	return t.generateICMPv6Error(ip, 3, 0, 0)
}

func (t *Translator) generateIPv6ParameterProblem(ip *layers.IPv6, pointer uint32) Packet {
	return t.generateICMPv6Error(ip, 4, 0, pointer)
}

func (t *Translator) generateICMPv6Error(ip *layers.IPv6, icmpType, code byte, rest uint32) Packet {
	outer := &layers.IPv6{
		Version:    6,
		NextHeader: layers.IPProtocolICMPv6,
		HopLimit:   64,
		SrcIP:      t.mapIPv4ToIPv6(t.ipv4RouterAddress),
		DstIP:      ip.SrcIP,
	}

	// RFC 4443 Section 2.4 (MUST): "Every ICMPv6 error message (type < 128) MUST include as much of the IPv6 offending
	// (invoking) packet (the packet that caused the error) as possible without making the error message packet exceed
	// the minimum IPv6 MTU"
	invoking := slices.Concat(ip.Contents, ip.Payload)
	if ip.HopByHop != nil {
		// gopacket decodes a leading Hop-by-Hop header out of the payload, so put it back.
		invoking = slices.Concat(ip.Contents, ip.HopByHop.Contents, ip.Payload)
	}

	// Link padding after the Payload Length is not part of the packet.
	invoking = invoking[:min(len(invoking), ipv6HeaderLength+int(ip.Length))]
	message := newICMPv6(outer, icmpType, code, rest, invoking[:min(len(invoking), ipv6ICMPErrorPayloadMaximum)])
	return serializePacket(completeOptions, outer, message)
}

func (t *Translator) generateIPv4SourceRouteFailed(ip *layers.IPv4) Packet {
	outer := &layers.IPv4{
		Version: 4, IHL: 5, Protocol: layers.IPProtocolICMPv4, TTL: 64,
		SrcIP: t.ipv4RouterAddress, DstIP: ip.SrcIP,
	}

	quote := slices.Concat(ip.Contents, ip.Payload[:min(len(ip.Payload), icmpErrorQuoteLength)])
	message := newICMPv4(3, 5, 0, quote)
	return serializePacket(completeOptions, outer, message)
}
